"""Treatment-related data models for MedCouncil."""

from __future__ import annotations

from typing import Optional

from pydantic import BaseModel, Field


class TreatmentRecommendation(BaseModel):
    """A single treatment recommendation."""

    treatment: str
    purpose: Optional[str] = None
    instructions: Optional[str] = None
    precautions: list[str] = Field(default_factory=list)


class TreatmentPlan(BaseModel):
    """Structured treatment plan generated by the treatment agent."""

    primary_condition: str

    recommendations: list[TreatmentRecommendation] = Field(
        default_factory=list
    )

    lifestyle_advice: list[str] = Field(default_factory=list)

    follow_up: Optional[str] = None

    warning_signs: list[str] = Field(default_factory=list)

    additional_tests: list[str] = Field(default_factory=list)

    notes: Optional[str] = None